    title: "Buy Medicare Contact Leads: Proven Strategies for Agents",
    metaTitle: "Buying Medicare Contact Leads: Proven Strategies",
    excerpt: "Proven strategies for buying and effectively working raw Medicare contact leads.",
    metaDescription: "Raw Medicare contact leads require more legwork than pre-qualified leads but often cost less per contact. Proven strategies for working this leaner lead type.",
    category: "Medicare Leads",
    readTime: "7 min read",
